class Animal:
    def __init__(self, source=None):
        if source is None:
            self.name = None
        else:
            self.name = source.name

    def clone(self):
        return Animal(self)

class Dog(Animal):
    def __init__(self, source=None):
        super().__init__(source)
        if source is None:
            self.breed = None
        else:
            self.breed = source.breed
    # clone() is NOT overridden here

