from abc import ABC, abstractmethod

class Prototype(ABC):
    @abstractmethod
    def clone(self):
        ...

class Config(Prototype):
    def __init__(self, source=None):
        if source is None:
            self.env = None
            self.timeout = None
        else:
            self.env = source.env
            self.timeout = source.timeout

    def clone(self):
        return Config(self)

c1 = Config()
c1.env = "staging"
c1.timeout = 30

c2 = c1.clone()
c2.env = "production"

print(c1.env, c2.env)
```

